WITH remaining_keys AS (SELECT device_code, firmware FROM device_readings EXCEPT SELECT device_code, firmware FROM device_readings WHERE status_bits <= 6), reconciled AS (SELECT s.* FROM device_readings s INNER JOIN remaining_keys k ON s.device_code = k.device_code AND s.firmware = k.firmware) SELECT device_code, SUM(CASE WHEN device_code = 'DV-02' THEN pressure ELSE 0 END) AS dv_02_pressure, ROUND(AVG(humidity), 2) AS avg_humidity FROM reconciled GROUP BY device_code
